<script lang="ts">
	import { onMount } from 'svelte';
	import { MediaQuery } from 'svelte/reactivity';

	let pathEl: SVGPathElement;
	let len = $state(0);
	let offset = $state(0);
	let fillOpacity = $state(new MediaQuery('(prefers-reduced-motion: reduce)').current ? 1 : 0);
	let opacity = $state(new MediaQuery('(prefers-reduced-motion: reduce)').current ? 1 : 0);
	let transition = $state('none');

	function play() {
		opacity = 1;
		fillOpacity = 0;
		transition = 'none';
		offset = len;

		requestAnimationFrame(() => {
			requestAnimationFrame(() => {
				transition = 'stroke-dashoffset 5s ease-in-out, fill-opacity 1s ease-in-out';

				offset = 0;

				setTimeout(() => {
					fillOpacity = 1;
				}, 1500);
			});
		});
	}

	onMount(() => {
		if (!pathEl) return;

		len = pathEl.getTotalLength();

		if (new MediaQuery('(prefers-reduced-motion: reduce)').current) {
			offset = 0;
		} else {
			play();
		}
	});
</script>

